expressions.expression:
// Feedwater peristaltic (stepper) dosing; gated by runSystem & not trip.
// Velocity is driven as a LEVEL (0 = stop) so every run/stop transition is a
// real value change and re-triggers the drive. (A separate STOP command would
// leave VELOCITY cached at the run value, so a re-run after a stop would be
// deduped and never re-fire -- the motor would stay still.)

// PRIME phase doses a fixed prime rpm (dead-reckon fill); RUN uses the
// mass-balance feedRpmSet (FeedFollow). Velocity is a LEVEL (0=stop). feedCmdRpm
// is the ACTUAL command (the sim reads it so the prime fill shows in inventory).
phase = static.mvrPhase
run = static.runSystem and (static.trip == 0) and (phase >= 1)
vel = 0
if ( phase == 1 ) then
    vel = static.feedPrimeRpm
endif
if ( phase >= 2 ) then
    vel = static.feedRpmSafe
endif
static.feedCmdRpm = vel
"STEP:Feed.ENABLE" = run
"STEP:Feed.VELOCITY" = vel

// Condensate: 2-level pump (HIGH 170 -> LOW 50) + flow-meter integration with
// per-fill SELF-CALIBRATION against the known 120 ml. The meter is noisy/off,
// but each pump cycle re-corrects condCalFactor so the accumulated product and
// level estimate stay accurate. Runs in real + sim (reads y* sensors).
// STEAM VENT (DO:VentValve): at startup the condenser output is mostly STEAM
// (HX hot, nothing subcools) until the makeup heater backs off and recovery
// takes over -- vent it outside until makeup is well down (hysteresis avoids
// chatter). While venting NO liquid collects and the flow meter reads ~0.
// condensate output is LIQUID once its outlet temp drops below boiling
// (yCondTemp from the HX-outlet TC). Above that it is STEAM: open the vent and
// IGNORE the flow meter (steam/air spins it). Hysteresis band avoids chatter.
condLiq = static.condLiquid
if ( static.yCondTemp < static.condLiquidTemp ) then
    condLiq = 1
endif
if ( static.yCondTemp > (static.condLiquidTemp + 2) ) then
    condLiq = 0
endif
if ( static.runSystem == 0 ) then
    condLiq = 0
endif
if ( static.mvrPhase < 3 ) then
    condLiq = 0
endif
static.condLiquid = condLiq
static.ventOpen = 1 - condLiq
"DO:VentValve" = static.ventOpen
dt = static.timeIncSec
// flow-meter integration must use the SAME elapsed-time base as the plant:
// real timeIncSec on hardware, but the sim-accelerated dt when simulating, so
// the calibration converges to the true meter error (not the simSpeed factor).
cdt = dt
if ( static.simEnable ) then
    cdt = dt * static.simSpeed
endif

// --- two-level pump hysteresis ---
pump = static.condPumpOn
if ( static.yCondHigh ) then
    pump = 1
endif
if ( static.yCondLow == 0 ) then
    pump = 0
endif
static.condPumpOn = pump
"DO:CondPump" = pump

// --- integrate the (mis-cal/noisy) flow meter ---
rawMl = 0
if ( static.condLiquid ) then
    rawMl = static.yCondFlow * 1000 * cdt / 60    // count the meter ONLY when LIQUID (temp < boiling)
endif
static.condFillRaw = static.condFillRaw + rawMl  // RAW accumulated over current fill
calMl = rawMl * static.condCalFactor             // calibrated ml this tick
static.condProduct = static.condProduct + calMl  // lifetime calibrated product
static.condVolEst  = static.condVolEst + calMl   // level estimate (corrected at sensors)
// FEED-SIDE (evaporator) INVENTORY dead-reckon: positive-displacement feed IN
// minus the calibrated distillate OUT (calMl). No level sensor needed -- the
// feed pump volume is exactly known and the OUT side is anchored by the
// condensate 120 ml high/low cal. PRIME fills it; FeedFollow holds it at
// evapLevelSet; watch it to see how close to dry the feed side is.
feedInMl = static.feedCmdRpm * static.feedStepsPerRev * static.feedLPerStep * 1000 * cdt / 60
// vapor leaving the feed side: METERED distillate when collecting; a blower-
// throughput estimate while VENTING (the flow meter reads ~0 then), so the
// dead-reckon keeps tracking through the steamy startup. Calibrate prodPerRpm.
static.blowerProdEst = 0
if ( static.heatOK ) then
    // ramp the estimate with boiling-readiness (eT 95->100) so it tracks the
    // ramping production during warm-up, not the full-boil value.
    static.blowerProdEst = clamp(static.prodPerRpm * static.blowerRpmSafe * clamp((static.yEvapTemp - 95) / 5, 0, 1), 0, 1)
endif
vaporOutMl = calMl
if ( static.ventOpen ) then
    vaporOutMl = static.blowerProdEst * 1000 * cdt / 60
endif
static.feedInvEst = clamp(static.feedInvEst + feedInMl - vaporOutMl, 0, 20000)

// --- LOW reached (pump just emptied below low): start a fresh fill, snap level ---
if ( static.yCondLow == 0 and static.prevCondLow == 1 ) then
    static.condFillRaw = 0
    static.condVolEst  = static.condLowML
endif
// --- HIGH reached (fill complete): the RAW fill should equal 120 ml -> recal ---
if ( static.yCondHigh == 1 and static.prevCondHigh == 0 ) then
    known = static.condHighML - static.condLowML
    if ( static.condFillRaw > 1 ) then
        newCal = known / static.condFillRaw
        static.condCalFactor = static.condCalFactor * 0.4 + newCal * 0.6
    endif
    static.condVolEst = static.condHighML
endif
static.prevCondHigh = static.yCondHigh
static.prevCondLow  = static.yCondLow

// Demister: drain whenever liquid water is present -- gated by runSystem so the
// relay doesn't chatter on sensor noise when the system is off.
"DO:DemisterDrain" = static.runSystem and (static.yDemisterWater > static.demisterThresh)

// Production control: trim the blower (compressor throughput) to hold the TARGET
// distillate rate. Measured production = the calibrated condensate flow meter,
// heavily smoothed (it is noisy and only flows while condensing). cdt
// accelerates the integral in sim (same trick as the flow-meter calibration) so
// the loop converges at the same wall-clock feel in real + sim.
cdt = static.timeIncSec
if ( static.simEnable ) then
    cdt = cdt * static.simSpeed
endif
// Update the measurement only while distillate is actually flowing, so the
// RUN-entry seed holds through the condensate formation lag (no drift to zero).
if ( static.yCondFlow > 0 ) then
    measProd = static.yCondFlow * static.condCalFactor
    static.prodMeas = static.prodMeas + (measProd - static.prodMeas) * clamp(cdt * 0.05, 0, 1)
endif
// Only trim the blower in RUN (phase 3) AND once distillate is actually flowing
// (yCondFlow>0) -- otherwise the controller winds up during the condensate
// holdup/formation lag (no measurement yet) and overshoots, draining the
// evaporator. Until then the blower holds its nominal rpm.
if ( static.autoBlow and (static.mvrPhase >= 3) ) then
    err = static.prodSetSafe - static.prodMeas
    rpm = static.blowerRpmSet + static.kProd * err * cdt
    rpm = clamp(rpm, static.blowerMinRpm, static.blowerMaxRpm)
    static.blowerRpmSet = rpm
endif

// Feed follows production (mass balance): feed in = distillate out + blowdown.
// Tracks MEASURED production. rpm = (L/min) / (stepsPerRev * LPerStep). Only in
// RUN (phase 3); PRIME/HEAT feed is handled by the startup state machine.
if ( static.autoFeed and (static.mvrPhase >= 2) ) then
    // hold evaporator level via the actual level (sim=inventory, real=AI:EvapLevel);
    // active in HEAT+RUN so feed replaces boil-off. Swap yEvapLevel->feedInvEst to
    // run on the no-sensor dead-reckon instead.
    levelTrim = static.kFeedLevel * (static.evapLevelSet - static.yEvapLevel)
    feedLpm = static.prodMeas * (1 + static.blowdownFrac) + levelTrim
    lpmPerRpm = static.feedStepsPerRev * static.feedLPerStep
    static.feedRpmSet = clamp(feedLpm / lpmPerRpm, 0, static.feedRpmMax)
endif

// ===== MVR PLANT SIMULATOR (blower-throughput-driven) =====
// Closed-loop lumped plant model. PRODUCTION (vapor boil-off) is set by BLOWER
// THROUGHPUT x boiling-readiness -- the compressor is the vapor pump. The
// compressed vapor condenses in the HX and that recovered latent heat (+ comp
// work) boils the next slug, so at steady state the makeup heater only covers
// losses + cold-feed sensible heat and BACKS OFF; blower RPM/bypass sets output.
// Startup: makeup drives the HX up to ~100C (output is mostly steam, no net
// liquid) until it backs off and the cold feed subcools the condensate -- only
// THEN does liquid condensate form and leave. Active only when simEnable=1.

if ( static.simEnable ) then
dt = static.timeIncSec * static.simSpeed
dt = clamp(dt, 0, 1.0)            // Euler stability guard
dtMin = dt / 60                  // minutes per tick (for ml/min flows)
static.simClock = static.simClock + dt
// slow production SURGE (two incommensurate sines + a little noise)
surge = 1 + static.simSurgeAmp * (sin(static.simClock*0.25) + 0.5*sin(static.simClock*0.83)) + 0.015*randn()
// cold-feed temperature fluctuation
static.simFeedTemp = static.simFeedSupply + static.simFeedNoise * randn()

// ---- effective actuator commands (from the controllers) ----
runOK = static.runSystem and (static.trip == 0)
blowCmd = 0
if ( runOK and (static.mvrPhase >= 2) ) then
    blowCmd = static.blowerRpmSafe
endif
feedCmd = static.feedCmdRpm
mkDuty = static.makeupDuty
shDuty = static.superDuty
bypass = clamp(static.bypassV / 10, 0, 1)
cpump  = static.condPumpOn

// ---- blower ballistics (motor inertia) ----
static.simBlowerRpm = static.simBlowerRpm + (blowCmd - static.simBlowerRpm) * dt / static.simTauBlower
blowFrac = clamp(static.simBlowerRpm / static.simBlowerRated, 0, 1.5)
compEff  = clamp(blowFrac * (1 - bypass), 0, 1.5)

// ---- PRODUCTION: blower throughput x boiling readiness (the blower IS the
// vapor pump). Nothing boils below ~95C; full at ~100C. Steady-state output
// scales with blower RPM/bypass, NOT with the makeup heater. ----
eT = static.simEvapTemp
boilReady = clamp((eT - 95) / 5, 0, 1)
vaporCap  = compEff * static.simVaporMax
prodTarget = vaporCap * boilReady * surge
static.simProd = static.simProd + (prodTarget - static.simProd) * dt / 2
static.simProd = clamp(static.simProd, 0, 5)
Qboil = static.simProd * static.simLatentPerLpm

// ---- evaporator pressure -> ballistic toward saturation Psat(evapT) ----
PsatEvap = exp((8.14019 - 1810.94 / (244.485 + eT)) * 2.302585) / 51.7149
static.simEvapPress = static.simEvapPress + (PsatEvap - static.simEvapPress) * dt / static.simTauP
static.simEvapPress = clamp(static.simEvapPress, 1, 60)

// ---- superheat from the SH cartridge: the heater W reaching the steam via the
// copper mesh, divided by the vapor heat capacity passing by. With a small 300W
// cartridge and the modest vapor flow this is hugely oversized -> the PWM duty
// sits low (a few %). Less production => less vapor => more superheat per watt. ----
shPower = shDuty * static.simSuperPow * static.simSHmeshEff
vaporKgs = static.simProd / 60
shCap = vaporKgs * static.simSteamCp
shTarget = 0
if ( shCap > 0.5 ) then
    shTarget = clamp(shPower / shCap, 0, 60)
endif
static.simSuperheat = static.simSuperheat + (shTarget - static.simSuperheat) * dt / static.simTauSH
static.simVaporIn = eT + static.simSuperheat

// ---- blower: modest pressure ratio (PR ~1.1-1.2) -> small saturation lift ----
PR = 1 + (static.simPRmax - 1) * compEff
steamP = static.simEvapPress * PR
static.simSteamPress = static.simSteamPress + (steamP - static.simSteamPress) * dt / static.simTauBlower
// steam chest CONDENSES at the saturation temp of the steam-side pressure
spmm = clamp(static.simSteamPress * 51.7149, 1, 1000000000000)
sct = 1810.94 / (8.14019 - log(spmm) / 2.302585) - 244.485
// HX (steam chest) = 24 lb steel + water with real thermal mass simChx. The
// produced vapor CONDENSES here, releasing its latent heat (+ compressor work);
// simRecovEff of it returns to boil the evaporator. The slab has to warm up
// first (warm-up LAG) before QoutHX can carry the load and makeup can back off.
QinHX = static.simProd * static.simLatentPerLpm * static.simRecovEff
QoutHX = static.simUAsteam * clamp(static.simSteamChest - eT, -200, 200)
static.simSteamChest = clamp(static.simSteamChest + (QinHX - QoutHX) / static.simChx * dt, static.simAmbient, 200)
// HX vertical GRADIENT: simSteamChest is the hot condensing TOP (~100C); the
// bottom is the cold-feed inlet. In counterflow the gradient develops once the
// system is boiling AND feeding (i.e. once makeup has backed off): the bottom
// cools from the top temp toward the feed inlet temp + a small approach. The
// condensate leaves at this cold bottom -- that is what subcools it.
feedActive = clamp(feedCmd * 0.1, 0, 1)
makeupOff = clamp((0.85 - mkDuty) / 0.45, 0, 1)   // 0 while makeup full, 1 once mostly off
counterflow = clamp(boilReady * feedActive * makeupOff, 0, 1)
hxBotTarget = static.simFeedTemp + static.simHXapproach + (static.simSteamChest - static.simFeedTemp - static.simHXapproach) * (1 - counterflow)
static.simHXbottom = static.simHXbottom + (hxBotTarget - static.simHXbottom) * dt / static.simTauHXgrad
static.simHXbottom = clamp(static.simHXbottom, static.simAmbient, 200)
// vapor OUT = inlet superheat + compression superheat (hotter than condensing temp)
compSH = static.simCompGain * (PR - 1)
voTarget = static.simVaporIn + compSH
static.simVaporOut = static.simVaporOut + (voTarget - static.simVaporOut) * dt / static.simTauBlower

// ---- evaporator energy balance (thermal LAG via simCevap). Qsteam (recovery)
// nearly cancels Qboil at steady state, so the makeup PI only has to cover
// Qfeed + Qloss and BACKS OFF once recovery is established. The cold feed is
// largely preheated by the outgoing condensate (simFeedRegen) -- that heat
// exchange is what subcools the condensate at the bottom of the HX. ----
feedFlow = feedCmd * static.feedStepsPerRev * static.feedLPerStep
feedEntry = static.simFeedTemp + static.simFeedRegen * (eT - static.simFeedTemp)
Qmakeup = mkDuty * static.simMakeupPow
Qsteam = QoutHX
Qfeed = feedFlow * 70 * clamp(eT - feedEntry, 0, 200)
Qloss = static.simUAloss * clamp(eT - static.simAmbient, 0, 300)
Qnet = Qmakeup + Qsteam - Qboil - Qfeed - Qloss
static.simEvapTemp = clamp(eT + (Qnet / static.simCevap) * dt, 0, 160)
// monitoring: instantaneous heat loss + total heat IN (makeup + recovery) (W)
static.simHeatLoss = Qloss
static.simHeatIn = Qmakeup + Qsteam

// ---- evaporator inventory (feed mass balance): feed in vs vapor boiled off ----
static.simEvapInv = clamp(static.simEvapInv + (feedFlow*1000 - static.simProd*1000) * dtMin, 0, 8000)

// ---- condensate: liquid only forms once makeup backs off and the cold feed
// subcools it -- the condensate is HOT at startup and cools as the gradient
// develops (simCondTemp). ALL boiled vapor condenses (mass-conserving, so the
// feed-side dead-reckon feedInvEst stays accurate). HX holdup adds the formation
// DELAY; then it fills the tank across the two level sensors. ----
// outlet condensate is LIQUID only when its temp is below boiling (condLiquid,
// the control temp gate). Until then it is STEAM -> vents, none collects, except
// a trim HX (if fitted) condenses trimFrac of it. (feed can absorb ~15%% of the
// steam latent heat it cools.)
feedCoolW = feedFlow * 70 * clamp(100 - static.simFeedTemp, 0, 200)
steamW = static.simProd * static.simLatentPerLpm
trimFrac = 0
if ( static.trimHX and steamW > 1 ) then
    trimFrac = clamp(feedCoolW / steamW, 0, 1)
endif
prodMl = static.simProd * 1000 * trimFrac
if ( static.condLiquid ) then
    prodMl = static.simProd * 1000
endif
static.simCondHold = clamp(static.simCondHold + prodMl * dtMin, 0, static.simCondHoldMax)
flowToTank = 0
if ( static.simCondHold >= static.simCondHoldMax ) then
    flowToTank = prodMl                              // holdup full -> condensate flows out
endif
pumpOut = 0
if ( cpump ) then
    pumpOut = static.simPumpMlMin
endif
static.simCondVol = clamp(static.simCondVol + (flowToTank - pumpOut) * dtMin, 0, 600)
static.simCondHigh = 0
if ( static.simCondVol >= static.condHighML ) then
    static.simCondHigh = 1
endif
static.simCondLow = 0
if ( static.simCondVol >= static.condLowML ) then
    static.simCondLow = 1
endif
// flow meter reads the flow PASSING it: STEAM spins it while venting (the
// control IGNORES it until condLiquid), the tank inflow once LIQUID. Mis-cal+noisy.
static.simCondFlow = static.simProd * static.simFlowCalErr * (1 + static.simFlowNoise * randn())
if ( static.condLiquid ) then
    static.simCondFlow = flowToTank / 1000 * static.simFlowCalErr * (1 + static.simFlowNoise * randn())
endif
static.simCondLevel = static.simCondVol / static.condHighML   // 0..1 proxy for charts

// ---- condensate OUTLET temp (the TC at the HX condensate output / flow meter).
// It reads ~the vapor/condensing temp while the output is STEAM, and drops below
// boiling as the cold feed cools it (gradient develops); a trim HX cools it
// further. That crossing is what turns the output to liquid + counts the meter. ----
subcoolT = static.simFeedTemp + static.simHXapproach
mkOff = clamp((static.condCoolDuty - mkDuty) / 0.1, 0, 1)   // cools to liquid as makeup drops below condCoolDuty
condOut = static.simSteamChest - (static.simSteamChest - subcoolT) * mkOff   // ~condensing(vapor) temp while steamy
condOut = condOut - (condOut - static.simFeedTemp) * trimFrac   // trim HX cools it further
static.simCondTemp = static.simCondTemp + (condOut - static.simCondTemp) * dt / 8
static.simCondTemp = clamp(static.simCondTemp, static.simAmbient, 200)
// cartridge surface temps for the heater TCs / overheat trips. Makeup tracks the
// boiling water when COVERED; it spikes when the charge drops (uncovered).
coverFrac = clamp(static.simEvapInv / static.simHtrCoverML, 0, 1)
mkSurf = eT + mkDuty * (static.simMakeupCovRise + static.simMakeupRise * (1 - coverFrac))
static.simMakeupHtrTemp = static.simMakeupHtrTemp + (mkSurf - static.simMakeupHtrTemp) * dt / static.simTauHtr
shSurf = static.simVaporIn + shDuty * static.simSuperRise
static.simSuperHtrTemp = static.simSuperHtrTemp + (shSurf - static.simSuperHtrTemp) * dt / static.simTauHtr

// ---- demister water (slow accumulation; DemisterDrain bleeds it) ----
drainOn = static.yDemisterWater > static.demisterThresh
static.simDemisterWater = clamp(static.simDemisterWater + (0.04 - drainOn * 0.5) * dt / 60, 0, 5)
// Flood is a SEPARATE, HIGHER fault sensor -- only rises when the drain
// can't keep up (water well above the drain level). Normal op -> ~0.
static.simDemisterFlood = clamp(static.simDemisterWater - (static.demisterThresh + 1.5), 0, 5)
endif
